// EN translation FIRST PASS. Literary editorial approval outstanding.
const OUTCOMES_EN_E221_E290 = Object.freeze({"E221.1":{"s":"The marauders knock down the ancient door, and Sev finally gets to his skull. Gold is found in the tomb, which the robbers are reluctant to share.","f":"When the door is first hit, the guardians of the tomb emerge from the walls. A skirmish begins."},"E221.2":{"s":"You pay the looters to leave, and they pack up their tools. Sev stays by the grating, listening to advice from his own skull."},"E221.3":{"s":"{{heroName}} frees the grating without disturbing the burial seals. Sev puts his skull back in place and rewards you with gold.","f":"The stone slab breaks off during work, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The grate collapses, but none of the eligible fighters are gravely wounded. The skull remains behind the stone."}},"E221.4":{"s":"You leave Sev near the tomb. “Try to remember what was in your head!” - the skull shouts after him."},"E222.1":{"s":"You enter the chapel and interrupt the silent formation. Among the offerings of the liberated choir, gold is discovered.","f":"A voice breaks into the silent song with an invisible, piercing blow. {{affectedHeroName}} is gravely wounded.","v":{"nf":"The chorus blasts the guests with an invisible sound, but none of the eligible combatants are gravely wounded. The singing doesn't stop."}},"E222.2":{"s":"You leave Emma provisions for the journey and advise her to leave the house before nightfall. Behind them, the ghosts open their mouths again in the same rhythm."},"E222.3":{"s":"{{heroName}} conducts a silent rite without giving the choir another voice. Emma rewards you with gold and supplies for ending the song.","f":"The ritual is reflected from the walls by a back wave, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The silent ritual is disrupted, but none of the eligible fighters are gravely wounded. Everyone still hears their song."}},"E222.4":{"s":"You cover your ears and walk past the chapel. Outside the door, Emma is left alone with six invisible melodies."},"E223.1":{"s":"Peck carefully gathers his fingers into a travelling bag and accepts the King's offer. Your party gains a disciplined, if rather fragile, recruit.","f":"At the last check, Peck's leg falls off, and he asks to reschedule his entry into the party. Can't hire him.","v":{"rs":"Peck is ready to serve, but there is no free space. Yora hands over the gold compensation, and the skeleton looks for another purpose."}},"E223.2":{"s":"You give Yora the gold for Peck's spare belts and equipment. The captain shares camping supplies and advice to keep everything in your pockets."},"E223.3":{"s":"{{heroName}} checks how Peck maintains formation and finds a place for him without making sharp turns. The skeleton joins the party.","f":"Even with the help of {{heroName}}, Peck loses his wrist again on the turn. The test must be completed without being hired.","v":{"rs":"{{heroName}} confirms Peck’s suitability for service, but the fighter cannot be taken. Yora gives the party gold instead of replenishment."}},"E223.4":{"s":"You wish Peck luck finding the right formation. The skeleton salutes, straightens his fingers and returns to his captain."},"E224.1":{"s":"You pay for the rooms and spend the night, trying not to count the guests. In the morning, Vela gives out supplies, although the plaque at the entrance now shows even fewer places."},"E224.2":{"s":"Behind the locked door is an old counting cabinet with gold, and the invisible voice finally falls silent.","f":"The door swings open into a corridor filled with armed strangers, whom the house had clearly counted in advance. A skirmish begins."},"E224.3":{"s":"{{heroName}} opens the lock from the outside and takes out the golden cache without crossing the threshold. The plaque at the entrance trembles, but does not change the number.","f":"A hidden bolt behind the door is triggered, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The locked room strikes out, but none of the eligible fighters is gravely wounded. The lock stays intact."}},"E224.4":{"s":"You leave the inn before the next headcount. Vela calls after you that there are four vacant rooms again."},"E225.1":{"s":"Priest Mort finally admits that the deceased was not an easy man. Hel nods happily and leaves the gold for the fair ceremony.","f":"Mort refuses to give a speech that will make the living even more hurtful. Hel argues with him right at the coffin."},"E225.2":{"s":"You ask Mort to finish the ceremony for the family's sake. Hel grants them the final word, and they share supplies in gratitude."},"E225.3":{"s":"{{heroName}} delivers a eulogy in which Hel is insufferable but dearly loved. The dead man offers gold with a satisfied gesture, and his family shares provisions.","f":"{{heroName}} finds too little in common between the memory of his relatives and Hel’s demands. The speech has to be postponed."},"E225.4":{"s":"You drive away while the procession chooses an appropriate adjective for Hel. The dead man still insists on the word “unbearable.”"},"E226.1":{"s":"Kshsh accepts the supplies, slowly straightens his eight legs and allows you to fit the saddle. Virra rewards you with gold for saving the day."},"E226.2":{"s":"You help place the saddle on Kshsha, and the spider finally gets up from its bedding. Virra pays gold for help.","f":"Kshsh fights off the saddle with his paws, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The spider knocks over the assistants, but none of the eligible fighters are gravely wounded. The saddle remains on the ground."}},"E226.3":{"s":"{{heroName}} finds a rubbed plate under the saddle straps that was causing Ksh pain. Virra gives gold and supplies as the spider calmly rises.","f":"{{heroName}} checks every strap but cannot discover why Kshsh refuses to stand. The spider remains curled around its basket."},"E226.4":{"s":"You leave Virra to discuss labor law with the eight-legged worker. Kshsh moves the basket towards him by one more paw."},"E227.1":{"s":"You detain a customer wearing a silver mask and find gold on him for a completed contract. Sariss takes the contract as proof of deception.","f":"The masked man calls for security, and Sariss rushes towards him with a dagger. A skirmish begins."},"E227.2":{"s":"You pay the guild gold and redeem the death order along with the seals. Sariss is finally able to put away his daggers."},"E227.3":{"s":"{{heroName}} finds a guild rule forbidding the client, assassin and target from being the same person without explicit consent. The guild refunds the gold.","f":"{{heroName}} finds only a clause about a fine for revising an already accepted order. The party loses the gold, but the case remains open."},"E227.4":{"s":"You do not interfere in a contract where the killer herself is listed as the victim. Sariss looks at the customer’s tea for a long time without touching his blades."},"E228.1":{"s":"You don't count the corners and find scouts near the wall, which has been nearby all along. Zaire pays in gold for the return of the people.","f":"The room changes dimensions on the fly, and {{affectedHeroName}} is gravely wounded by the moving wall.","v":{"nf":"The octagonal room is rebuilt, but no eligible combatants are gravely wounded. The scouts are not found."}},"E228.2":{"s":"You block the entrance and leave the tower without new visitors. From the eighth corner the voice of the missing scout is heard once again."},"E228.3":{"s":"{{heroName}} follows the sound of footsteps instead of counting corners. The scouts escape and reward you with gold and supplies.","f":"The impossible geometry closes around {{affectedHeroName}}, inflicting a grave wound.","v":{"nf":"The room winds its way back to the door, but no eligible combatants are gravely wounded. The search stops."}},"E228.4":{"s":"You leave Zyre beside the tower. From within comes a triumphant shout: “I think we've found the ninth!”"},"E229.1":{"s":"You pay Niris for a detour and pass by the crystal with its endless questions. An offended “not interested” comes from the stone."},"E229.2":{"s":"You tell a story that no one standing nearby has heard, and the crystal opens a passage with gold in delight.","f":"The crystal declares your story boring and calls its armed guardians. A skirmish begins."},"E229.3":{"s":"Upon impact, the crystal shatters, revealing the gold veins inside. Niris looks at you as if he has lost an argument with a mineral for the first time.","f":"The protective crystal responds with a blow and summons the guardian of the passage. The battle begins."},"E229.4":{"s":"You turn away without telling the crystal a story. It shouts one final question after you, but no one is obliged to answer."},"E230.1":{"s":"You convince Seira and Velis to accept the usual agreement while the spiders fight over the empty frames. The houses pay gold for the completed truce.","f":"Seira declares the paper contract a violation of customs, and the argument turns into a skirmish."},"E230.2":{"s":"You give gold to both houses, buying time for new negotiations. The messengers return the supplies, and the spiders are taken to different tents."},"E230.3":{"s":"{{heroName}} negotiates away from the fighting spiders, and both houses agree to sign a truce on the already completed web. The party receives gold and supplies.","f":"{{heroName}} tries to negotiate the wording, but both houses insist on first deciding who broke the last web. Nobody signs a thing."},"E230.4":{"s":"You decline to become a third house in the dispute between Seira, Velis and their spiders. Another frame crashes down behind you."},"E231.1":{"s":"You pay Moro for ruining the cake and force both assassins to put away their blades. The pastry chef immediately asks who will replace the broken plates."},"E231.2":{"s":"The Fox and Shael agree to compensate the confectioner for the damage, and give part of the gold to the party for mediation.","f":"Both assassins accuse you of supporting your rival and turn their daggers on the new guests. A skirmish begins."},"E231.3":{"s":"{{heroName}} studies the boot prints and identifies which assassin first stepped into the cake and broke cover. They reward the detective work with gold.","f":"{{heroName}} sees only mixed traces in the cream and cannot separate the steps of the Fox from Shael. The dispute continues."},"E231.4":{"s":"You leave two assassins near the destroyed cake. Moro loudly demands the return of at least the silver stand."},"E232.1":{"s":"You answer that the question weighs as much as the answerer is willing to bear, and the door suddenly moves away. Gold is found in the mine.","f":"In response to the next answer, the door becomes heavier and sags, requiring the floor to be strengthened. Supplies are spent on materials."},"E232.2":{"s":"You go around the mysterious door through the adjacent masonry and take supplies out of the mine.","f":"The nearby wall crumbles under the tools, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The masonry crumbles, but none of the eligible fighters are gravely wounded. The passage remains closed."}},"E232.3":{"s":"{{heroName}} strengthens the door frame and lifts the door with levers without asking a single question. Behind it lie gold and supplies.","f":"The stone slab slips onto {{affectedHeroName}}'s hand, causing a grave wound.","v":{"nf":"The heavy slab is torn from its supports, but none of the eligible fighters are gravely wounded. The mine entrance cannot be opened."}},"E232.4":{"s":"You leave Brokk and his miners at the door made heavy by unanswered questions. The foreman asks you not to raise any more."},"E233.1":{"s":"One of the new hats reveals Grim's golden rings, and another contains a neatly braided strand of beard. The merchant pays the reward in gold.","f":"The suspects take the search as an insult to the entire family and rush to defend their hats. A skirmish begins."},"E233.2":{"s":"You give Grim the gold for the missing jewelry. The merchant thanks, but promises to continue the search for forty-seven years of growth."},"E233.3":{"s":"{{heroName}} finds fresh hairs on the floor and a trace of an expensive blade leading to a cache of rings. Grim gives out gold for a solution.","f":"{{heroName}} discovers that all four equally visited the room at night. It is impossible to confidently name the kidnapper."},"E233.4":{"s":"You leave Grim, Nol and four suspects with new hats. The merchant demands an immediate ban on the sale of scissors in the city."},"E234.1":{"s":"You enter the mine and find an old cashbox beside the working face. Its gold goes to your party, though the owners of the pickaxes remain unseen.","f":"Around the bend in the tunnel an armed brigade appears, not wanting to show their faces. The battle begins."},"E234.2":{"s":"You take some of the ore from an already loaded minecart and sell it for gold.","f":"Armed guards come out of the mine and demand the return of someone else's workings. A skirmish begins."},"E234.3":{"s":"{{heroName}} checks the cracks after the collapse and finds a safe place to extract valuable ore. Kora pays in gold for the examination.","f":"A support plate breaks off from the ceiling, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The support collapses, but none of the eligible fighters are gravely wounded. The entrance has to be closed."}},"E234.4":{"s":"You leave the unknown miners' cart untouched. Today's date appears on its boards before your eyes."},"E235.1":{"s":"By morning the mug was empty, although no one approached the chair. Dagna thanks the party for their patience with supplies.","f":"At dawn, the mug remains full, and the students look at Dagna anxiously. Custom does not provide an answer."},"E235.2":{"s":"You quietly empty the mug, and Dagna gives out the gold for the restored sign. There are enough students so that no one asks questions.","f":"Dagna notices the substitution, and for the attempt at deception she has to give up supplies. The mug is placed again in front of the chair."},"E235.3":{"s":"{{heroName}} conducts a ritual of remembrance, and for the first time the students talk about the master without fear of an empty mug. Dagna gives gold and supplies.","f":"{{heroName}} cannot discover who drank the ale before. Dagna leaves the mug standing until the next dawn."},"E235.4":{"s":"You leave Dagna to wait for an answer from the empty chair. The students argue whether it is possible to at least move the mug closer to the edge."},"E236.1":{"s":"You watch the third shot from behind cover, and at last the cannonball flies forward. Beli pays gold for witnesses to a successful test.","f":"The cannonball flies back again and seriously injures {{affectedHeroName}}.","v":{"nf":"The third shot goes backwards, but no eligible combatants are gravely wounded. The test is considered unsuccessful."}},"E236.2":{"s":"You buy supplies from the crew and leave the shooting range for new experiences. Torr assures that only the rear hemisphere is now considered dangerous."},"E236.3":{"s":"{{heroName}} notices the inverted charging channel and fixes the error. The cannon fires forward, and the dwarves reward with gold.","f":"While adjusting the fuse, the recoil is triggered, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The ignition mechanism produces a dangerous shock, but no eligible combatants are gravely wounded. Correction is delayed."}},"E236.4":{"s":"You depart before the third shot. Behind you, Beli and Torr argue about which direction now officially counts as forward."},"E237.1":{"s":"You recognize the breakdown of the first brigade as an insured event, and Helda pays the money. For the investigation, the party is given gold.","f":"The second crew accuses the decision of fraud and grabs the tools as weapons. A skirmish begins."},"E237.2":{"s":"You give funds to the second brigade, and it thanks the party with supplies. The first requires immediately recalculating the size of the misfortune.","f":"The first brigade declares the distribution of the fund unfair and challenges the rivals to a skirmish."},"E237.3":{"s":"{{heroName}} compares records and proves where the accident is real and where it is an expensive imitation. Helda pays in gold and supplies for the saved fund.","f":"{{heroName}} discovers that both brigades use the same dubious acts. The decision has to be postponed."},"E237.4":{"s":"You do not undertake to distribute the common fund of mutual hatred. Helda sits directly on the chest and asks everyone not to break anything yet."},"E238.1":{"s":"You pay Azel for a key with clear terms, and he gives it out along with supplies for the road. The demon warns about another minor flaw."},"E238.2":{"s":"You take the key, despite the warning, and it opens a small golden cache near the road stone. Azel is sincerely surprised.","f":"The key burns the King's palm, causing a serious injury. Azel wearily says: “I asked you not to take it.”","v":{"nf":"The key works dangerously, but the King is not gravely wounded. You don’t find the castle for which it was needed."}},"E238.3":{"s":"You demand compensation for the time spent on dangerous offers, and Azel, dreaming of finishing the bargain, gives away the gold.","f":"The demon declares the demand extortion and calls in armed assistants. A skirmish begins."},"E238.4":{"s":"You thank Azel for his rare trading honesty and leave without the key. He closes the box with dangerous goods with relief."},"E239.1":{"s":"You share provisions with the demons, who finally stop gnawing on the crockery. Malg rewards you with gold for saving the dishes."},"E239.2":{"s":"You help drive the hungry demons from the kitchen, and Malg pays gold so he can light the oven again.","f":"Hungry demons mistake you for new distributors and attack you with knives and forks. A skirmish begins."},"E239.3":{"s":"{{heroName}} lines up the demons and separates what they can eat from the plates they cannot. Malg rewards you with gold and supplies.","f":"{{heroName}} does not have time to explain the difference between food and dishes, and the line falls apart. The kitchen remains closed."},"E239.4":{"s":"You depart, and the goat trots after you as far as the bend. Malg shouts that it was supposed to be his lunch."},"E240.1":{"s":"Five minutes pass, the world remains intact, and the demons pay out the winnings in gold. Zerr demands that “almost came true” be entered into the journal.","f":"Red skies scare players, bets are recalculated according to new rules, and your winnings are not paid."},"E240.2":{"s":"You force Zerr to stop the hysteria in the square, and grateful passers-by pay in gold for the ensuing silence.","f":"The demons consider trying to stop the prophet an attack on their entertainment. A skirmish begins."},"E240.3":{"s":"{{heroName}} identifies a rare atmospheric phenomenon, not the end of the world. The demons reward you with supplies for sparing them a panic.","f":"{{heroName}} does not have time to establish the cause of the red sky before the end of five minutes. Zerr declares this additional evidence."},"E240.4":{"s":"You step away from Zerr and count the remaining minutes. The world does not end, but the prophet is already preparing an explanation."},"E241.1":{"s":"You find the lost treaty in a roadside ditch, where Tev has already searched three times. The demon pays in gold for a saved place in the underworld.","f":"The paper is neither in the bags nor under the hooves, and the archivist is already close. Tev asks at least not to tell his superiors about him."},"E241.2":{"s":"You give Tev gold to abandon the search and send him away. The farmer declares it the best bargain he has made in forty years."},"E241.3":{"s":"{{heroName}} requires the original, and Tev cannot prove the obligation without paper. The demon pays off with gold to stop the proceedings.","f":"Tev calls the hellish bailiffs, considering the legal dispute an obstacle to recovery. A skirmish begins."},"E241.4":{"s":"You leave Tev to rummage in the ditch and the peasant to enjoy his freedom from evidence. There is less and less time left before sunset."},"E242.1":{"s":"You give the shivering demon supplies, and his teeth finally stop chattering. Roch rewards your unusual assistance with gold."},"E242.2":{"s":"You carry the demon to a hot forge, where he can finally warm up. Roch shares supplies in thanks for saving his blanket and stove.","f":"As you carry the demon, he bursts into flame without warning, gravely wounding {{affectedHeroName}}.","v":{"nf":"A dangerous flash disrupts the carrier, but none of the eligible fighters are gravely wounded. The demon remains by the fire."}},"E242.3":{"s":"{{heroName}} arranges a stretcher with a heat-resistant coating, and the demon is delivered to the forge without a fire. Roch pays in gold and adds supplies.","f":"{{heroName}} finds out that no fabric available can withstand the heat. Carrying has to be postponed."},"E242.4":{"s":"You leave Roch with the demon under the smoking blanket. The blacksmith is already looking for a second, thicker one."},"E243.1":{"s":"You find the missing cow in a lava-filled storeroom and lead it out through the barn. The farmers reward you with supplies while Xal apologises for the wrong address.","f":"The demons declare the cow to be part of hell's inventory and take up arms. A skirmish begins."},"E243.2":{"s":"You close the incorrectly configured portal and return the barn to the owners. Before closing, Xal throws in a gold payment for the corrected error.","f":"The hell door resists closing, and armed guards burst through the opening. A skirmish begins."},"E243.3":{"s":"{{heroName}} removes the frame along with the fasteners, and the portal disappears without damaging the shed. Farmers pay in gold and supplies.","f":"The frame suddenly changes weight, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The portal frame falls, but no eligible combatants are gravely wounded. The door remains open."}},"E243.4":{"s":"You walk around the barn in a wide arc. Behind, the farmers again demand a cow, and Xal demands a map of the third lava gallery."},"E244.1":{"s":"You invite Riel to spend the prepared blessing to help the entire village. The angel distributes supplies, and the recovered old woman is the first to thank the herbalist.","f":"Riel cannot change the purpose of an already prepared miracle. The village is left without additional help."},"E244.2":{"s":"You leave gold to the village in the name of the King. Riel stands nearby, trying to decide if this counts as a miracle without the radiance."},"E244.3":{"s":"{{heroName}} helps Riel turn a belated ceremony into a quiet blessing for the village. Grateful residents share gold and supplies.","f":"{{heroName}} does not find a way to perform the ritual without the person for whom it was intended. The angel can only accept the delay."},"E244.4":{"s":"You leave Riel and the herbalist to argue about which of them helped the patient better. The old woman invites both of them to tea."},"E245.1":{"s":"You give Lyon the feather brought by the wind, and Saf, after a long check, recognizes it as suitable. A grateful angel shares supplies.","f":"The inspector finds a different mark on the feather and refuses to count it as the missing one. The register stays open."},"E245.2":{"s":"You pay for the missing feather from the treasury, and Saf puts the long-awaited seal. Lyon looks at the empty space in the wing with relief."},"E245.3":{"s":"{{heroName}} finds a report that records the feather's loss in the line of duty. Saf closes the case and rewards your work with gold.","f":"{{heroName}} does not detect a proper signature on the report. The inspector demands that everything be re-registered."},"E245.4":{"s":"You pass by the celestial check, leaving Lyon and Safa above the magnifying glass. The wind brings another white feather."},"E246.1":{"s":"You acknowledge the cloud as heavenly property, and Oris pays gold for the decision. The cloud immediately pours rain on him.","f":"The cloud leaves the border line without waiting for the celestial jurisdiction to be formalized. The dispute is not resolved."},"E246.2":{"s":"The border guard gets the right to inspect the cloud and thanks the party with supplies. It is unknown where he plans to look for contraband.","f":"Oris does not recognize the right of an earthly official to inspect the sky. The inspection is canceled until the dispute is resolved."},"E246.3":{"s":"You wait for the cloud to float away from the dispute area. Two officials simultaneously declare this a legal border crossing."},"E246.4":{"s":"You dismiss both officials and take the gold set aside for an urgent ruling. The cloud drifts away before the argument can resume.","f":"Oris and the border guard call the guards on both sides of the road. A skirmish begins."},"E247.1":{"s":"You rouse Merad with a firm tap on the shoulder, and the angel lowers his spear for the first time in ninety years. The pilgrims reward you with gold.","f":"The crack under the guard's feet responds with a hot blast, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The red-hot crack widens, but none of the eligible fighters are gravely wounded. The angel remains motionless."}},"E247.2":{"s":"You lead the pilgrims off the hill before the ground completely cracks. The priest supplies the party with supplies.","f":"The pilgrims refuse to leave the guardian whom they have been grateful to all their lives. Evacuation fails."},"E247.3":{"s":"{{heroName}} discovers under the hill an ancient seal that Merad held with his vigil. For the find, the priest gives gold and supplies.","f":"An attempt to approach the seal causes a surge of heat, and {{affectedHeroName}} is severely injured.","v":{"nf":"The seal repels explorers, but no eligible combatants are gravely wounded. The true threat remains undiscovered."}},"E247.4":{"s":"You leave Merad on guard without breaking his ninety-year fast. The cracks under the spear are slowly creeping towards the road."},"E248.1":{"s":"You buy supplies from Foss and receive them between two crates with wing attachments. The line of angels moves one place forward."},"E248.2":{"s":"You unload the Foss tables and sort out forgotten orders. The master issues a gold payment for the vacated workshop.","f":"When dismantling storage boxes, some of your own supplies are spoiled. The line is still not moving."},"E248.3":{"s":"{{heroName}} braces the heavy fittings and helps Keri straighten her wing. Foss rewards you with gold and provisions.","f":"{{heroName}} sees that some of the fastenings are made for a different wing size. Urgent work has to be postponed."},"E248.4":{"s":"You leave the workshop without joining the queue to repair other people's wings. Foss is already arguing with the angel who brought one feather."},"E249.1":{"s":"You break down the chapel door and find golden offerings near an empty chair. The light goes out as soon as the party passes the threshold.","f":"Armed guardians emerge from the glow, angered by your forced entry into the chapel. A battle begins."},"E249.2":{"s":"You direct people away from the locked chapel, preventing curious people from approaching the walls. The chair inside continues to scrape the floor."},"E249.3":{"s":"{{heroName}} enters the chapel and discovers that the light is coming from an old seal under the chair. Sister Abel thanks with gold and supplies for the restored calm.","f":"The seal flashes when approached, and {{affectedHeroName}} is severely wounded.","v":{"nf":"The light strike stops the inspection, but no eligible combatants are gravely wounded. The chapel remains closed."}},"E249.4":{"s":"You leave before dawn without checking the light source. The shadows of the trees are still visible through the walls of the chapel."},"E250.1":{"s":"You convince Iara and Veh to share the reward, and for the first time both acknowledge the other's achievement. The child’s family gives the party gold for ending the dispute.","f":"Neither angel nor demon agrees to share the honor of salvation. The girl quietly says that she would prefer to separate the disputants themselves."},"E250.2":{"s":"You give the family gold without figuring out who gets the glory. Parents thank the party with supplies."},"E250.3":{"s":"{{heroName}} asks the girl to name what helped her first: the light allowed her to escape, fear stopped her pursuers. Both saviors make a decision and hand over the gold and supplies.","f":"{{heroName}} offers a general verdict, but Iara and Veh still argue about the order of miracles. The reward has not been distributed."},"E250.4":{"s":"You leave before the argument between angel and demon turns into a treatise on the nature of good. The girl erases her circle with chalk."},"E251.1":{"s":"You find a forgotten dragon's hoard in the red cave. Rakhs studies his own handwritten warning and admits that it proved remarkably useful.","f":"The red cave turns out to be the lair of armed creatures awakened by the search. The battle begins."},"E251.2":{"s":"In one of the ordinary caves you discover a small part of a forgotten treasure. Rakhs thanks in gold for the find.","f":"The search drags on until night and consumes supplies, but the next mark on the map leads into the void."},"E251.3":{"s":"{{heroName}} checks several crosses, separating old marks from fresh ones. The party finds gold in an unnamed cave.","f":"On the way back from the gorge, {{affectedHeroName}} is gravely wounded.","v":{"nf":"Checking the caves ends in a dangerous collapse, but none of the eligible fighters are gravely wounded. The treasure is not found."}},"E251.4":{"s":"You wish Rakhs patience and leave him with his grandchildren and the map. The old dragon is already thoughtfully putting up a new cross."},"E252.1":{"s":"You support Kaara's desire to keep her father's scales in the temple. The family thanks the party with supplies for their decision.","f":"Kaara does not make a decision without her brother's consent and continues to hold the scales in front of the family altar. The dispute does not end."},"E252.2":{"s":"You recognize Tesh's right to wear scales on his shield in memory of his father. He hands over gold for support.","f":"Kaara refuses to give up the scales for the shield and demands to first discuss her mother's will. There is no concession."},"E252.3":{"s":"{{heroName}} reads the inscription on the inside of the scales and finds out what custom the father wanted to preserve. The family stops arguing and thanks with gold and supplies.","f":"{{heroName}} cannot decipher the last faded word. Neither Kaara nor Tesh will give way, and the scales remain between them."},"E252.4":{"s":"You leave Kaara and Tesh to face a motherly question about memory. The scales lie on the table between the temple and the shield."},"E253.1":{"s":"You buy a vial of dragon's breath and receive travel supplies from the alchemist as part of the deal. The young worker again leans towards the copper funnel."},"E253.2":{"s":"You insist that Sarr pay the young draconian his fair share. The settled dispute earns your party gold.","f":"The alchemist declares that his working conditions are no one's business and calls for armed assistants. A skirmish begins."},"E253.3":{"s":"{{heroName}} finds deductions in the contract the young draconian never understood and demands a fair reckoning. Sarr hands over gold and supplies.","f":"{{heroName}} finds signatures on all pages, but cannot prove coercion. The worker remains at the funnel."},"E253.4":{"s":"You refuse to buy fire, which is used to profit from the exhaustion of others. Sarr hastily assures the next buyer that everything is voluntary."},"E254.1":{"s":"You hold the flame in the pouring rain until the forging is complete. Varek pays the promised gold, and Mira smiles for the first time.","f":"The rain extinguishes the forge, and it takes supplies to relight it. Varek declares this a harsh but rewarding test."},"E254.2":{"s":"You contribute provisions for fuel and materials, allowing Mira to finish before the next downpour. Varek rewards the help with gold."},"E254.3":{"s":"{{heroName}} installs a removable canopy over the forge without destroying the blacksmith tradition. Varek pays in gold for saving the fire.","f":"The canopy support falls in a gust of wind, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The temporary shelter is torn away by the wind, but none of the eligible fighters is gravely wounded. The forge goes out again."}},"E254.4":{"s":"You leave Varek to argue with the rain and Mira to carry the coal. The blacksmith assures that metal will one day appreciate perseverance."},"E255.1":{"s":"You support Kesh every step of the way until the huge suit of armor reaches the ceremonial circle. The family thanks with supplies.","f":"Kesh cannot keep his helmet upright and sits down in the middle of the ceremonial ground. The trial must be postponed."},"E255.2":{"s":"The family agrees that becoming an adult cannot be measured by the size of one's great-grandfather's breastplate. The mentor pays gold for preserving Kesh's dignity.","f":"The mentor refuses to change an ancient custom. Kesh keeps rattling inside his oversized armour."},"E255.3":{"s":"{{heroName}} teaches Kesh to take short steps and rest the armour's weight on his hips. He completes the ceremony, and his family rewards you with gold and supplies.","f":"During training the heavy armour topples onto {{affectedHeroName}}, inflicting a grave wound.","v":{"nf":"The armor topples over on the landing, but none of the eligible fighters are gravely wounded. The test is stopped."}},"E255.4":{"s":"You leave the family to its traditions. Behind you, Kesh takes his first step and vanishes inside his own helmet."},"E256.1":{"s":"You reach a boiling circle on the lake and find golden objects rising from the bottom. The fishermen do not dare to approach the boat.","f":"An armed creature rises from the red glow, forcing the party into battle."},"E256.2":{"s":"You buy supplies from the fishermen and leave the strange lake. The nets at the pier are still hot."},"E256.3":{"s":"{{heroName}} reads the signs on the coastal slabs and recognizes the location of the ancient fiery spring. For the discovery, fishermen hand over gold and supplies.","f":"Warm scales flare up in his hands, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The scales produce a fiery burst, but none of the eligible fighters are gravely wounded. The origin of the glow remains a mystery."}},"E256.4":{"s":"You leave the lake undisturbed. The red glow passes along the bottom again as the fishermen roll up their nets."},"E257.1":{"s":"You buy Ovry's contract from the collector, and the fox wins the right to keep his own tail. He rewards you with supplies and promises to read the small print."},"E257.2":{"s":"You drive away the collector with scissors, and the grateful Ovry hands over the gold for the saved tail.","f":"The collector brings armed guards to execute the contract. A skirmish begins."},"E257.3":{"s":"{{heroName}} proves that a tail cannot be delivered ‘after natural death’ while its owner is still alive without changing the entire bargain. The collector refunds the gold.","f":"{{heroName}} finds a clause regarding a penalty for termination. The party has to give up part of the gold, and the dispute continues."},"E257.4":{"s":"You leave Ovri between the tailor and the collector. The scissors click, and for the first time the fox demands a copy of the contract in large print."},"E258.1":{"s":"You spend an hour rescuing the King's cloak from three persistent lion cubs. Rasha thanks with supplies for the whole brood.","f":"The lion cubs play with the convoy so enthusiastically that some of the provisions are torn apart. Rasha returns to the empty bag."},"E258.2":{"s":"You pay the merchant for an extra hour of supervision, and he reluctantly comes down from the tree. One boot remains with the lion cubs."},"E258.3":{"s":"{{heroName}} arranges a hunting game for the lion cubs without real prey. Rasha thanks with gold and supplies.","f":"One of the lion cubs mistakes his hand for prey, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The cubs chase their guards into the bushes, but none of the eligible fighters is gravely wounded. The babysitting ends here."}},"E258.4":{"s":"You decline the job of babysitting lion cubs and leave before they discover the spare cloak. Rasha watches you go with obvious regret."},"E259.1":{"s":"You hand Burg the payment, and he takes a step back just enough to let the party through. The sign at the post remains untouched."},"E259.2":{"s":"You explain to Burg that twenty-three years without a shift turns an order into a mistake. He accepts the argument, and the caravan shares the supplies.","f":"Burg perceives the dispute with the order as an attempt to break through by force and stands across the pass. A skirmish begins."},"E259.3":{"s":"{{heroName}} moves the stone sign along with the post markings, and Burg is already guarding the side of the road. The caravan thanks with gold and supplies.","f":"While carrying the sign, {{affectedHeroName}} is gravely wounded by a falling slab.","v":{"nf":"The sign is torn from its mountings, but none of the eligible fighters are gravely wounded. The post remains closed."}},"E259.4":{"s":"You spend supplies searching for another pass. Burg stands in his place, without turning to the departing caravan."},"E260.1":{"s":"You sit beside Kha and address the empty space. An unseen visitor leaves gold among the ashes, and for once the hyena is not laughing alone.","f":"Alien laughter is heard right behind the fighters, and armed shadows emerge from the fire. A skirmish begins."},"E260.2":{"s":"You lead Kha away from the fire, and her invisible friend does not follow. The pack rewards the restored peace with provisions.","f":"Kha refuses to leave her friend, whom only she can see. The flock remains in fear of the empty space."},"E260.3":{"s":"{{heroName}} finds a second paw print in the ashes and realizes that the guest exists separately from Kha. The flock pays gold for the solution.","f":"The invisible creature responds to the check with a blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The invisible guest pushes the researchers out of the circle of light, but none of the eligible fighters are gravely wounded. Kha continues to laugh."}},"E260.4":{"s":"You avoid a fire where only one side of the conversation can be heard. Another paw print appears in the ashes behind you."},"E261.1":{"s":"You support the prosecution, and Missa finds the mouse merchant guilty after checking the right to the cheese. The plaintiff thanks in gold for the decision.","f":"The judge cannot prove that the piece of cheese belonged to anyone at all. The charge remains unsolved."},"E261.2":{"s":"You defend the mouse and point out the lack of documentation about the owner of the cheese. A grateful merchant gives away supplies.","f":"Missa finds the invoice with the plaintiff's name on it and refuses to accept the defense's arguments. The mouse remains to wait for the verdict."},"E261.3":{"s":"{{heroName}} studies the invoices while Missa tries not to stare at the defendant's tail. Both sides accept the verdict and offer gold and supplies.","f":"{{heroName}} finds out that the cheese was resold several times without receipts. Ownership cannot be established."},"E261.4":{"s":"You leave Missa to keep order in the cat court. The mouse tries to keep its tail motionless."},"E262.1":{"s":"You follow the answering voice to an old cache of gold beside a rocky ledge. Moor recognises where his home once stood.","f":"Armed strangers emerge from behind the ledge, mimicking the voice of Moor's son. A skirmish begins."},"E262.2":{"s":"You convince Moor not to respond to an unfamiliar echo and to listen to the words of his granddaughter. The family thanks with supplies.","f":"Moor repeats his son’s phrase again, and the same strange answer comes from afar. It is impossible to stop him."},"E262.3":{"s":"{{heroName}} discovers that the second voice comes from an old acoustic vault in the rocks. Moor thanks him with gold and supplies for the explanation.","f":"A stone slab falls off in a crevice, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"A dangerous crevice forces the search to be abandoned, but none of the eligible fighters are gravely wounded. The second voice is not explained."}},"E262.4":{"s":"You leave Moor with his granddaughter on the quiet plain. She calls to her grandfather in her own voice, without borrowing another's words."},"E263.1":{"s":"You admit that G-17 is right: the conditions of service do not comply with the contract. The repairman thanks you for the solution and gives you supplies.","f":"The official rejects G-17's complaint and tells him to immediately get out into the rain. The golem does not move."},"E263.2":{"s":"You support the official, and the golem is ordered to return to patrol. For confirming the order, the party is given gold.","f":"The repairman shows the rusted hinges and seeks a deferment of the order. The patrol cannot be resumed."},"E263.3":{"s":"{{heroName}} cleans the joints and installs rain guards. The official pays gold, and the repairman adds provisions.","f":"The wet mechanism jams the tool, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The mechanism produces dangerous recoil, but none of the eligible combatants are gravely wounded. G-17 remains under the canopy."}},"E263.4":{"s":"You don't get involved in a dispute about dry operating conditions. G-17 goes deeper under the roof following a new drop of rain."},"E264.1":{"s":"You take apart A-9's casing and find a hidden voice module with valuable gold contacts. The workshop's owner pays you for restoring order.","f":"The internal mechanism works before the hand can be removed, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The casing lashes out, but none of the eligible fighters is gravely wounded. The source of the voice remains inside."}},"E264.2":{"s":"You pay the owner of the workshop to turn off the machine. A-9 whispers “thank you,” and the second voice only manages to say the first word."},"E264.3":{"s":"{{heroName}} distinguishes between two signals with different delays and finds the source of the second voice without opening it. The hostess gives out gold for the solution.","f":"The second voice turns into a dangerous magical flash, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The invisible signal repels the explorers, but no eligible combatants are gravely wounded. A-9 continues to whisper."}},"E264.4":{"s":"You walk around the automaton without putting your ear to its chest. From afar you can hear: “Don’t listen to him.”"},"E265.1":{"s":"You agree with K-4, and the barn is moved to another site. The watchtower's keeper rewards the restored sunlight with gold.","f":"Residents refuse to demolish the new barn and call the guard against the decision. A skirmish begins."},"E265.2":{"s":"You support the residents and stop the tower that threatens the barn. The village thanks with supplies.","f":"K-4 refuses orders from the people who blocked her sunlight. You cannot shut the tower down."},"E265.3":{"s":"{{heroName}} places reflective panels so that the morning light falls on K-4 again. The village thanks with gold and supplies.","f":"{{heroName}} discovers that the available mirrors will not withstand the wind. The tower continues to demand that the sun be moved."},"E265.4":{"s":"You leave K-4 to argue with the barn and the celestial body. The caretaker is already looking for a more patient engineer."},"E266.1":{"s":"You pay off Lom's debt and open the crate without demanding his service in return. The wooden automaton climbs out on his own."},"E266.2":{"s":"You uphold the merchant's right to recover the debt and receive gold for the ruling. From the crate, Lom loudly announces his disagreement.","f":"The girl brings Lom's supporters and demands to stop selling the living assistant. A skirmish begins."},"E266.3":{"s":"{{heroName}} finds that Lom was never listed among the pledged goods. The merchant refunds the gold after the dispute.","f":"{{heroName}} finds only incomplete receipts, and the merchant charges an inspection fee. The party loses gold."},"E266.4":{"s":"You refuse to interfere with Lom's sale. A clear voice comes from the crate: “I can hear everything.” The merchant hastily steps away."},"E267.1":{"s":"You go up to the clock and discover a secret niche with gold behind the laughing gear. The second voice in the alley falls silent.","f":"At the mechanisms you are met by armed night guards, who somehow know about your visit. A skirmish begins."},"E267.2":{"s":"You pay for an overnight stay far from the clock and receive supplies from the owner of a quiet inn. Laughter reaches here only as a faint echo."},"E267.3":{"s":"{{heroName}} lingers at the tower and finds a second, hidden clockwork that answers the first. Em pays in gold for the detected malfunction.","f":"At midnight, the tower responds to the check with a blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The midnight mechanism is triggered, but no eligible combatants are gravely wounded. The laughter continues."}},"E267.4":{"s":"You leave the square before dark. Em is still waiting for the clock to start laughing."},"E268.1":{"s":"The automaton recognises the real King and opens an ancient vault filled with gold. For once, the city council agrees unanimously to switch off the spare crown.","f":"The Machine declares both monarchs active and raises armed guards for the fortress. The battle begins."},"E268.2":{"s":"You order the spare monarch dismantled. Among his parts, you find the gold of the former court.","f":"The watchdogs regard the order as an attempt on the throne. A skirmish begins."},"E268.3":{"s":"You leave the spare King off. The archivist records in the journal that the main copy arrived undamaged."},"E268.4":{"s":"You pay the archivist and take the supplies from the basement. The reserve monarch remains seated on his iron throne."},"E269.1":{"s":"You drive the bear out of Pel's bed, and the forester thanks you with gold for returning the lodge.","f":"The beast wakes up from the noise and rushes to protect someone else's bed. A skirmish begins."},"E269.2":{"s":"You place the supplies by the door, and Pel continues to wait for the lodger to vacate the bed. A sleepy muzzle pokes out of the window."},"E269.3":{"s":"{{heroName}} lures the bear with the smell of food, clearing Pel's way into the lodge. The forester rewards you with gold and supplies.","f":"The bear suddenly jumps out of the door, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The beast pushes everyone away from the porch, but none of the eligible fighters are gravely wounded. The lodge remains occupied."}},"E269.4":{"s":"You leave Pel on the porch and the bear in his bed under the covers. For the first time, the forester is thinking about building a second lodge for himself."},"E270.1":{"s":"You go further and intercept the golden cash box of the robbers who came at the signal of the crows. The loot ends up with the party.","f":"The robbers correctly read the number of croaks and choose a convenient place to attack. A skirmish begins."},"E270.2":{"s":"You leave some of the supplies for the birds, and the crows switch to eating instead of counting. The party passes by without any new alarm."},"E270.3":{"s":"{{heroName}} follows the calls of the birds and finds the hideout of the robbers with the gold. Widow Nara thanks for the revelation.","f":"At a robber ambush, {{affectedHeroName}} is gravely wounded before he can retreat.","v":{"nf":"Reconnaissance discovers an ambush, but none of the eligible fighters are gravely wounded. Robbers' gold remains inaccessible."}},"E270.4":{"s":"You turn off the road before the next row of crows. Their croaking fades among the trees."},"E271.1":{"s":"A white deer leads you to a forest cache with supplies, and the silver ringing sounds further and further. The beast leaves without being touched.","f":"Armed hunters, who do not want guests, come out to answer the bells. A skirmish begins."},"E271.2":{"s":"You take the silver bell from the deer's neck and sell it for gold. The beast leaves silently.","f":"The deer strikes with its antlers in defense, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The deer sharply knocks the hand away and leaves, but none of the eligible fighters is gravely wounded. The bell remains with the beast."}},"E271.3":{"s":"{{heroName}} follows the deer at a distance and finds gold and provisions among the forest stones. The bell never betrays the hidden scout.","f":"On a forest slope, {{affectedHeroName}} is gravely wounded when he stumbles upon a hidden trap.","v":{"nf":"The reconnaissance stumbles upon a trap, but none of the eligible fighters are gravely wounded. The deer trail is lost."}},"E271.4":{"s":"You leave the white deer with its bell and do not answer the call. Three silver ringing sounds gradually merge into one."},"E272.1":{"s":"You dismantle part of the dam and free the flooded path. The beavers immediately take over the new section.","f":"The beavers protect the structure and bring their armed guard party onto the road. A skirmish begins."},"E272.2":{"s":"You pay Lem for a boat and cross the flooded area. One beaver closely monitors the quality of the crossing."},"E272.3":{"s":"{{heroName}} finds a place to pass without destroying the dam, and Lem shares the gold and supplies for the successful project.","f":"A log from the dam breaks and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The log disrupts construction work, but none of the eligible combatants are gravely wounded. The passage is not yet open."}},"E272.4":{"s":"You spend supplies on a long, dry detour around the flooded road. Behind you, the beavers carry off another sheet of Lem's plans."},"E273.1":{"s":"You again bring the dog to the old soldier and leave them alone. The owner thanks you for your patience and gives you supplies.","f":"The dog breaks free and returns to the northern crossroads before he sees the soldier's house. It is impossible to reconcile them."},"E273.2":{"s":"You leave food for the dog at the intersection and move on. He eats without taking his eyes off the northern road."},"E273.3":{"s":"You pay the innkeeper to take care of the old dog. He promises to bring food every evening, as much as needed."},"E273.4":{"s":"You don’t stop the dog from waiting for the one who once went north. An old soldier lives very close by, but the intersection remains empty."},"E274.1":{"s":"You help the fishermen hold their nets until the catch stops pulling skyward. They give the party a choice of fish to add to its provisions.","f":"The flying carp tears the net from his hands, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"Nets are torn into the sky, but none of the eligible combatants are gravely wounded. The catch is lost."}},"E274.2":{"s":"You get to the shore and find golden objects that fell from the nets under the place where the fish took off.","f":"An armed creature descends from a dark cloud above the river. The battle begins."},"E274.3":{"s":"{{heroName}} determines that the shadow attracts river creatures through an unusual air current. Fishermen pay in gold and supplies for warning.","f":"The force from the cloud hits the shore, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"A sudden air strike disrupts observations, but none of the eligible fighters are gravely wounded. The source of the shadow is hidden."}},"E274.4":{"s":"You retreat to the protection of the rocks as the fish continue to rise into the cloud. The fishermen look up for a long time with empty nets."},"E275.1":{"s":"You pay Nilly gold for yesterday, which cannot be returned. The fairy accepts the compensation and finally releases the merchant."},"E275.2":{"s":"You convince Nilly that the day spent cannot be returned as goods, and the merchant pays the party gold for protection.","f":"The fairy accuses you of stealing time and calls her armed friends. A skirmish begins."},"E275.3":{"s":"{{heroName}} asks Nilly to explain how yesterday can become someone else's property. The fairy drops her demands and hands over gold.","f":"{{heroName}} gets entangled in a fairy contract, and Nilly demands payment for court minutes. The party loses gold."},"E275.4":{"s":"You refuse to judge the deal based on the day used. Nilly asks the merchant if he will sell her tomorrow morning."},"E276.1":{"s":"You leave supplies for the wedding feast to the ants, and they return Ker's boot. The soldier thanks in gold for the saved shoes."},"E276.2":{"s":"You disperse the ant formation and return the boot to its owner. Ker pays in gold to get rid of barefoot service.","f":"Fairy ants attack with needles in formation, protecting the wedding house. A skirmish begins."},"E276.3":{"s":"{{heroName}} offers the ants an empty box instead of a boot, and they happily postpone the wedding. Ker gives out gold and supplies.","f":"{{heroName}} cannot understand the ceremonial signals of the ants, and they do not agree to the exchange. The boot remains with the music inside."},"E276.4":{"s":"You wish Ker an easy journey and move on. The soldier hops on one leg following his own festive shoes."},"E277.1":{"s":"You answer the voice that the mushroom has chosen for you and find a golden cache in the white circle. Al remains at the clearing with other people's memories.","f":"The mushroom releases burning spores and {{affectedHeroName}} is severely injured.","v":{"nf":"The mushroom releases dangerous spores, but no eligible combatants are gravely wounded. The conversation ends."}},"E277.2":{"s":"You set fire to the mushroom outside the circle and find gold among its charred roots.","f":"The fairies declare arson a violation of the ban and come out to defend the clearing. A skirmish begins."},"E277.3":{"s":"{{heroName}} deciphers the ancient signs on the white stones and discovers how the mushroom borrows voices. The fairies reward you with gold and supplies.","f":"The protective circle flares up and seriously injures {{affectedHeroName}}.","v":{"nf":"The white stones respond with a strike of light, but no eligible combatants are gravely wounded. The mystery of the mushroom remains unanswered."}},"E277.4":{"s":"You leave the white circle untouched and leave El with the mushroom speaking in his mother's voice. The fairies watch you depart in silence."},"E278.1":{"s":"You help the fairies clear the aphids from the cabbage patch and receive supplies from the grateful village. The ladybird leads the victory parade.","f":"Insects break through the formation, and some of the camp supplies perish in the confusion. The campaign is dragging on."},"E278.2":{"s":"You give the village supplies to defend the garden bed, and the ladybug commander rewards the party with gold."},"E278.3":{"s":"{{heroName}} organizes the washing away of aphids with water and saves the bed without a pitched battle. The elders give thanks with gold and supplies.","f":"{{heroName}} cannot supply water to the far section of the garden bed. The fairies remain with the same plan of attack."},"E278.4":{"s":"You leave the fairies to prepare for the great cabbage war. Ladybug knocks on the shields with her paw even harder."},"E279.1":{"s":"You carry the butterfly to the next fork, and it finally spreads its wings. The postman thanks you for the delivery and gives you supplies.","f":"The butterfly settles on the saddle and refuses to fly even near the desired path. The addressee remains unknown."},"E279.2":{"s":"You open the scroll and find an indication of a golden cache near the road. The butterfly immediately flies away.","f":"The seal with the eye closed flashes and {{affectedHeroName}} is severely injured.","v":{"nf":"The letter responds with a dangerous outburst, but none of the eligible fighters are gravely wounded. Can't read it."}},"E279.3":{"s":"{{heroName}} notices in which direction the butterfly turns its antennae before each fork. The postman thanks him with gold and supplies for finding the route.","f":"{{heroName}} cannot work out the destination from the butterfly's movements. It stays perched on the saddle, and the delivery is delayed."},"E279.4":{"s":"You return the butterfly and scroll to the fairy postwoman. She sighs and goes looking for a steed more obedient than a Knight."},"E280.1":{"s":"The king puts on the dew crown for one breath, and the fairy court recognizes him as its temporary guardian. For performing the ritual, the party receives gold and supplies.","f":"Transparent drops burn the King's head with icy heat, leaving a serious wound.","v":{"nf":"The dew flashes cold, but the King is not gravely wounded. The ceremony is interrupted."}},"E280.2":{"s":"You give gold to the fairy court instead of agreeing to the crown. The courtiers accept the gift and retreat."},"E280.3":{"s":"You refuse the fairies without taking your eyes off the empty throne of dew. The fairy court reaches a decision and lets you pass.","f":"The fairy guard considers the refusal to be a violation of ancient custom and closes the road. A skirmish begins."},"E280.4":{"s":"You leave before full dawn, without letting the crown touch the King. The first rays of the sun turn its drops into ordinary water."},"E281.1":{"s":"You pay Pix eight gold pieces, and he solemnly moves your stool closer to the doctor's door. An old woman with a stick threatens to sue him."},"E281.2":{"s":"You remove Pix's six empty stools, returning the old lady to her place. She thanks with supplies while the goblin counts the lost profits.","f":"Pix presents the “right of waiting” paper, and the line begins to argue again. The old woman remains behind the stools."},"E281.3":{"s":"{{heroName}} proves that empty stools cannot hold places in a queue for the sick. Pix returns the gold taken unlawfully.","f":"{{heroName}} does not find a city ban on paid stools, and Pix collects gold during the inspection."},"E281.4":{"s":"You pass by the line to see the doctor. Pix is ​​already offering the old lady a discount on her own first place."},"E282.1":{"s":"You buy an insurance policy from Kik and receive a promise to return the money after death. The goblin smiles as if he has already received the second installment."},"E282.2":{"s":"You force Kik to refund the policyholders and collect the gold legally awarded to your party.","f":"The goblin calls security, accusing you of trying to declare an insurance claim early. A skirmish begins."},"E282.3":{"s":"{{heroName}} reads the contract out loud, and buyers find out that there is no one to legally receive the payments. Kik returns the gold to avoid trial.","f":"{{heroName}} finds such a confusing clause about recipients that the dispute has to be postponed. The Goblin continues to sell policies."},"E282.4":{"s":"You refuse to insure against your own death from a person who expects to never meet the payout recipient. Kik is already looking for a new client."},"E283.1":{"s":"The soup turns out to be quite edible, and the caravan finds a shortcut along the last visible turn. The remaining provisions are shared with the party.","f":"Half the word “DANGER” turns out to be more important than the recipe, and armed raiders are waiting for you around the bend in the road. A skirmish begins."},"E283.2":{"s":"You pay Rek for a new route, and the scout leads the caravan away from Glum's cauldron. The cook vows never to put maps in soup again."},"E283.3":{"s":"{{heroName}} reconstructs the route from a sodden scrap of the map and marks in the ground. On the correct path, you find gold and provisions.","f":"The guess about the turn turns out to be wrong, and {{affectedHeroName}} is gravely wounded in dangerous terrain.","v":{"nf":"The route leads to a dangerous slope, but none of the eligible fighters is gravely wounded. You must find another way."}},"E283.4":{"s":"You use up your supplies on a safe detour and leave Glum with the map soup. Rek carefully hides the remaining corner of the map."},"E284.1":{"s":"You place a bid, then sell the thoroughly ordinary copper coin to another collector at a profit. The sale yields gold.","f":"The auctioneer hits the hammer before your next bid, and the deposited gold remains with the merchants."},"E284.2":{"s":"You show the buyers that the coin is ordinary, and Bryk pays in gold to stop the dangerous trade.","f":"Buyers consider the revelation an attempt to disrupt the auction and surround the party with security. A skirmish begins."},"E284.3":{"s":"{{heroName}} finds out that the first bets were made by Bryk’s assistants, creating the appearance of a stir. The party receives gold for exposure.","f":"{{heroName}} does not find a direct connection between the bids and the auctioneer. The coin continues to rise in price."},"E284.4":{"s":"You watch as a tattered coin reaches the price of a small house. Bryk looks as if he himself is beginning to believe in its value."},"E285.1":{"s":"You pay your way back, Zeke sets up a ladder, and the man finally climbs down from the roof. The grateful survivor leaves supplies."},"E285.2":{"s":"You demand Zeke provide a free ride for a stranded client. The goblin gives in and returns some of the gold.","f":"Zeke claims that you are trespassing on his business and calls the staircase security. A skirmish begins."},"E285.3":{"s":"{{heroName}} finds a safe place to lower a rope without Zeke's ladder. The rescued man pays you in gold.","f":"During the descent, the support breaks, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The support is torn off, but none of the eligible fighters are gravely wounded. The man remains on the roof."}},"E285.4":{"s":"You leave as Zeke announces a new hourly rate for waiting for the stairs. An indignant scream is heard from the roof."},"E286.1":{"s":"You break the outer lock and retrieve a purse of gold from the chest. The buyer immediately checks what else might have been inside.","f":"The defense mechanism hits the revealers, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The chest responds with a defensive strike, but no eligible combatants are gravely wounded. The content remains locked."}},"E286.2":{"s":"You pay Tick for an ‘emergency key’, and the goblin solemnly hands over another metal contraption. The buyer insists on testing whether it opens anything."},"E286.3":{"s":"{{heroName}} finds the chest's hidden bottom bolt and opens it without damaging the contents. The buyer thanks with gold and supplies.","f":"The protective loops are sharply compressed, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The hinges are torn off the guides, but none of the eligible fighters are gravely wounded. The chest remains closed."}},"E286.4":{"s":"You leave the buyer with the safest chest in the world. A faint knock is heard from inside again, and Tick repeats the terms of the warranty."},"E287.1":{"s":"You get Krak to admit the forgery, and the goblin returns the gold to Fael and the party. The sparkling halo is finally removed.","f":"Krak declares that the goods were purchased without the right of return and calls security. A skirmish begins."},"E287.2":{"s":"You give Krak the gold and buy supplies instead of a new celestial item. Fael asks not to take anything glowing."},"E287.3":{"s":"{{heroName}} finds in the trade rules a clause about the false origin of the goods. Krak is forced to return the gold for the fake halo.","f":"{{heroName}} discovers that the receipt merely says ‘shining ring’. The seller cannot be forced to accept a return."},"E287.4":{"s":"You pass by a market where Fael is struggling with an overheated halo. Krak already offers a cooling pad for a fee."},"E288.1":{"s":"You help Odo fit the bracket, bringing the missing half of the rainbow into line. The dwarf rewards the engineering help with gold.","f":"The metal distorts the colours again. Odo admits the problem is more complicated than a simple truss, and the rainbow remains broken."},"E288.2":{"s":"You help Mellie remove the iron, and the colors gradually return to their places. The fairy shares supplies in gratitude.","f":"Odo refuses to remove the support from the unfinished rainbow. The dispute between the two masters continues."},"E288.3":{"s":"{{heroName}} fits a temporary support that holds without nailing light or colour in place. Odo and Mellie reward the solution with gold and supplies.","f":"While installing the support, {{affectedHeroName}} is gravely wounded from a broken bracket.","v":{"nf":"The temporary clamp breaks, but none of the eligible fighters are gravely wounded. The rainbow remains broken."}},"E288.4":{"s":"You leave the dwarf to screw on the rainbow, and the fairy to be indignant at the iron on the flowers. The order of the shades changes again."},"E289.1":{"s":"You support Brook and help arrange a safe place for the ghostly child near the fire. The orc thanks you for your understanding and gives you supplies.","f":"The shaman insists that the ghostly child needs a memory of home, not a new bed. Brook is left without the support of the elders."},"E289.2":{"s":"You help the shaman finish the rite, and the child sees the path beyond the ruins. Brook says goodbye, and the shaman pays you in gold.","f":"The ghost does not want to leave Brook and hides behind his back. The ceremony has to be stopped."},"E289.3":{"s":"{{heroName}} discovers the name and route to the child's old home in his memories. Brook rewards you with gold and supplies for restoring them.","f":"The Rite of Remembrance responds with a heavy blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The child's memory resists interference, but none of the eligible fighters are gravely wounded. His name remains forgotten."}},"E289.4":{"s":"You leave Brook with the child, who you can see right through. The orc carefully explains to him where the shoes will be in the house."},"E290.1":{"s":"You cut the web and lower Toriel to the ground. The angel rewards you with gold for saving his wings—and his dignity.","f":"The spider mistakes the cutting of the web for an attack and rushes at the party. A skirmish begins."},"E290.2":{"s":"You leave supplies for the spider, and it reluctantly takes its paw away from Vesa. Toriel can finally be removed from the trap."},"E290.3":{"s":"{{heroName}} distracts the spider by moving the saddle while Vesa frees the angel's wings. Toriel pays in gold and gives out supplies.","f":"The spider thwarts the rescue attempt and gravely wounds {{affectedHeroName}}.","v":{"nf":"The spider blocks access to the network, but none of the eligible fighters are gravely wounded. The angel remains hanging over the road."}},"E290.4":{"s":"You leave Vesa and Toriel to deal with the right to the web. The angel asks to at least turn him to face the road."}});
export { OUTCOMES_EN_E221_E290 };
